import {movementLabel,saleByKey} from './business-read.js';
export function createMoneyHistoryUI(env){
  const {state,esc,money,icon,accountName,render,doc,go}=env;
  const values={all:'Todos',sale:'Cobros de venta','debt-payment':'Abonos de fiado',expense:'Gastos',purchase:'Mercadería',contribution:'Aportes',withdrawal:'Retiros',move:'Traspasos','sale-correction':'Correcciones'};
  function source(e){const [kind,id]=e.source.split(':');if(kind==='sale')return `<button class="text-btn" data-sale="${id}">Ver venta${icon('chevron')}</button>`;if(kind==='debt'){const p=state.debtPayments.find(v=>v.id===id);return p?`<button class="text-btn" data-wf="debt" data-id="${p.debtId}">Ver fiado y abono${icon('chevron')}</button>`:'';}if(kind==='receipt'||kind==='receipt-payment'){const receiptId=kind==='receipt'?id:state.receiptPayments.find(p=>p.id===id)?.receiptId;return `<button class="text-btn" data-wf="receipt-source" data-id="${receiptId}">Ver recepción${icon('chevron')}</button>`;}if(kind==='correction')return `<button class="text-btn" data-correction="detail" data-id="${id}">Ver corrección${icon('chevron')}</button>`;return '';}
  function screen(){const kind=state.workspaceMoneyKind,from=state.workspaceMoneyFrom,to=state.workspaceMoneyTo,valid=!from||!to||from<=to,entries=valid?state.ledger.filter(e=>(state.moneyFilter==='all'||e.legs.some(l=>l.account===state.moneyFilter))&&(!from||e.day>=from)&&(!to||e.day<=to)&&(kind==='all'||kind==='purchase'?kind==='all'||['purchase','purchase-payment'].includes(e.kind):kind==='sale-correction'?['sale-correction','payment-correction'].includes(e.kind):e.kind===kind)).slice().reverse():[];
    return `<details class="history-filters" ${state.workspaceFiltersOpen?'open':''}><summary>Filtrar movimientos</summary><div class="workflow-form"><label>Cuenta<select id="workflow-money-account">${['all','cash','brubank','mp','nx'].map(a=>`<option value="${a}" ${a===state.moneyFilter?'selected':''}>${a==='all'?'Todas las cuentas':accountName(a)}</option>`).join('')}</select></label><label>Tipo<select id="workflow-money-kind">${Object.entries(values).map(([k,t])=>`<option value="${k}" ${k===kind?'selected':''}>${t}</option>`).join('')}</select></label><label>Desde<input id="workflow-money-from" type="date" value="${esc(from)}"></label><label>Hasta<input id="workflow-money-to" type="date" value="${esc(to)}"></label></div></details>${!valid?'<p class="error">Desde debe ser anterior o igual a Hasta.</p>':''}${entries.length?entries.map(e=>`<article class="money-record"><div><strong>${movementLabel(e.kind)}</strong><span>${e.day} · ${env.dateTime(e.at)}</span></div><p>${esc(e.note)}</p>${e.legs.map(l=>`<p>${accountName(l.account)} <b>${l.amount>0?'+':'−'}${money(Math.abs(l.amount))}</b></p>`).join('')}${source(e)}</article>`).join(''):'<p class="caption">Sin movimientos para estos filtros.</p>'}`;}
  function change(e){const key={'workflow-money-account':'moneyFilter','workflow-money-kind':'workspaceMoneyKind','workflow-money-from':'workspaceMoneyFrom','workflow-money-to':'workspaceMoneyTo'}[e.target.id];if(key){state[key]=e.target.value;state.workspaceFiltersOpen=true;render();}}
  return {screen,change};
}
